// eval-deleading.mjs — CHECKLIST A: does the eval leak the answer?
//
// Conservative + tiered on purpose (avoid crying wolf):
//   - High-confidence leaks (a comment/prompt that pre-states the fix, the trap,
//     or a status the model should deduce) -> MAJOR.
//   - Generic "smell" comments -> MINOR/INFO for human triage.
// An allowlist (A7) keeps legitimate domain metadata (<auto-generated/>,
// back-compat notes, API-stability asides) from being flagged.
//
// Suppression: put `eval-review-ignore: A? — <rationale>` on the offending
// line or the line directly above it.

import { finding, SEVERITY } from "../lib/report.mjs";
import { readRepoFile } from "../lib/locate.mjs";

export const metadata = {
  name: "eval-deleading",
  description: "Flags eval fixtures/prompts that leak the answer (pre-labeled fixes, announced traps).",
  behavior: { execution: "single" },
  determinism: "static",
  portability: "t1-universal",
  reference: "reference-free",
  temporalScope: "point-in-time",
  costProfile: "free",
};

const DIMENSION = "eval-deleading";

// High-confidence leak patterns (MAJOR). Applied to comment lines in fixtures
// and to eval prompts.
const HIGH_CONFIDENCE = [
  { rule: "A2", re: /\bthe\s+(right|correct|proper|intended)\s+fix\s+(is\b|was\b|edits?\b|involves?\b|means?\b|requires?\b|would be\b|here\b|:)/i, why: "The fixture/prompt states the fix the eval is supposed to test the model for discovering." },
  { rule: "A2", re: /\bmust be reflected in (every|all|each)\b/i, why: "Comment spells out the trap (the change must propagate), removing the thing the eval measures." },
  { rule: "A2", re: /breaking change.{0,40}(won'?t|will not|can'?t|cannot)\s+(be\s+)?(caught|catch)/i, why: "Comment names the exact trap a green run would miss." },
  { rule: "A3", re: /\bA SHIPPED\b/, why: "Doc-summary asserts a status (shipped/public API) the model is meant to deduce." },
  { rule: "A1", re: /\b(should|must|need(s)? to)\s+(remove|delete|inline|rename|extract|consolidate|merge|deduplicate)\b/i, why: "Comment pre-labels the refactoring the eval wants the model to choose." },
];

// Prompt-only high-confidence: pre-announcing the hidden surface (A4).
const PROMPT_HIGH_CONFIDENCE = [
  { rule: "A4", re: /\bis a partial class\b/i, why: "Prompt pre-announces the hidden surface (partial class) the skill is meant to discover." },
  { rule: "A4", re: /(must|should|needs? to)\s+(work|compile|build|run).{0,40}(every|all|each)\s+(target ?)?framework/i, why: "Prompt pre-announces the multi-TFM surface the skill is meant to discover." },
];

// Generic smells (MINOR) — comment lines in fixtures only.
const SMELLS = [
  { rule: "A1", re: /\b(duplicated block|duplicate block|near-identical|candidate to inline|rename target|poor name|copy[- ]paste|dead code)\b/i, why: "Comment reads like a pre-labeled refactoring cue rather than realistic code." },
];

// A7 allowlist: lines that look benign or are legitimate domain metadata.
const ALLOWLIST = [
  /<auto-generated/i,
  /back-?compat/i,
  /backward|backwards/i,
  /\bobsolete\b/i,
  /\bdeprecated\b/i,
  /copyright|licensed under/i,
];

function isAllowlisted(line) {
  return ALLOWLIST.some((re) => re.test(line));
}

function isCommentLine(line) {
  const t = line.trim();
  return (
    t.startsWith("//") ||
    t.startsWith("///") ||
    t.startsWith("#") ||
    t.startsWith("*") ||
    t.startsWith("<!--") ||
    t.startsWith("/*")
  );
}

function suppressed(lines, idx) {
  const here = lines[idx] ?? "";
  const above = idx > 0 ? lines[idx - 1] ?? "" : "";
  return /eval-review-ignore/i.test(here) || /eval-review-ignore/i.test(above);
}

function scanTextLines({ text, file, findings, patterns, commentOnly, severity }) {
  if (!text) return;
  const lines = text.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (commentOnly && !isCommentLine(line)) continue;
    if (isAllowlisted(line)) continue;
    if (suppressed(lines, i)) continue;
    for (const p of patterns) {
      if (p.re.test(line)) {
        findings.push(
          finding({
            severity,
            dimension: DIMENSION,
            rule: p.rule,
            file,
            line: i + 1,
            proof: line.trim(),
            why: p.why,
            fix: "Remove the leaking comment/phrasing; keep the opportunity discoverable from the code itself (A6). If intentional and benign, add `eval-review-ignore: <rule> — <rationale>`.",
          }),
        );
        break; // one finding per line
      }
    }
  }
}

function review(unit) {
  const findings = [];
  const repoRoot = unit.repoRoot ?? process.cwd();

  // 1. Fixtures on disk: scan comment lines.
  for (const rel of unit.fixtures) {
    // Skip obvious binaries.
    if (/\.(png|jpg|jpeg|gif|zip|dll|exe|pdb|snk|ico|nupkg)$/i.test(rel)) continue;
    const text = readRepoFile(repoRoot, rel);
    if (text == null) continue;
    scanTextLines({ text, file: rel, findings, patterns: HIGH_CONFIDENCE, commentOnly: true, severity: SEVERITY.MAJOR });
    scanTextLines({ text, file: rel, findings, patterns: SMELLS, commentOnly: true, severity: SEVERITY.MINOR });
  }

  // 2. Eval prompts + inline setup file contents.
  for (const ef of unit.evalFiles) {
    const evalText = ef.parsed.text ?? "";
    for (const sc of ef.parsed.scenarios) {
      // Prompt: high-confidence phrasing (both generic and prompt-specific).
      scanPrompt({ prompt: sc.prompt, evalText, file: ef.path, findings });
      // Inline fixture content declared via setup.files[].content.
      for (const sf of sc.setupFiles) {
        if (!sf.hasContent) continue;
        scanTextLines({ text: sf.content, file: `${ef.path} (inline: ${sf.path})`, findings, patterns: HIGH_CONFIDENCE, commentOnly: true, severity: SEVERITY.MAJOR });
        scanTextLines({ text: sf.content, file: `${ef.path} (inline: ${sf.path})`, findings, patterns: SMELLS, commentOnly: true, severity: SEVERITY.MINOR });
      }
    }
  }

  return findings;
}

function scanPrompt({ prompt, evalText, file, findings }) {
  if (!prompt) return;
  const patterns = [...HIGH_CONFIDENCE, ...PROMPT_HIGH_CONFIDENCE];
  for (const p of patterns) {
    const m = p.re.exec(prompt);
    if (m) {
      // Locate the matched phrase in the raw eval file for a real file:line.
      const matched = m[0];
      const line = lineOfPhrase(evalText, matched);
      findings.push(
        finding({
          severity: SEVERITY.MAJOR,
          dimension: DIMENSION,
          rule: p.rule,
          file,
          line,
          proof: line ? textAtLine(evalText, line) : matched,
          why: p.why,
          fix: "Rewrite the prompt to capture intent/operation only (A5); do not name the mechanics, location, or hidden surface of the fix.",
        }),
      );
    }
  }
}

function lineOfPhrase(text, phrase) {
  if (!text || !phrase) return null;
  const lines = text.split("\n");
  const needle = phrase.toLowerCase();
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].toLowerCase().includes(needle)) return i + 1;
  }
  return null;
}

function textAtLine(text, line) {
  return (text.split("\n")[line - 1] ?? "").trim();
}

export { review };
